export const isExplicitMealLoggingIntent = (text: string): boolean => {
  const normalized = text.trim();
  return (
    normalized.length >= 2 &&
    !/\b(?:workout|training|exercise|session)\b/i.test(normalized) &&
    mealLoggingPatterns.some((pattern) => pattern.test(normalized))
  );
};
